  for (const [re, name, forced] of registry) {
    if (re.test(host)) { sourceName = name; if (forced) hint = forced; break; }
  }
  if (/bbc\.(co\.uk|com)$/.test(host)) {
    if (path.startsWith('/sport/')) hint = 'Sports';
