`section: ${yaml(section)}`,
`type: ${yaml(type)}`,
`author: ${yaml('Nuvellum Global Desk')}`,
`date: ${yaml(date)}`,
`publishedAt: ${yaml(publishedAt)}`,
`readingTime: ${yaml(readingTime)}`,
`image: ${yaml(image)}`,
`imageAlt: ${yaml(imageAlt)}`,
`status: ${yaml(status)}`,
