    .replace(/\s(?:href|xlink:href)\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi,'')
    .replace(/javascript\s*:/gi,'')
    .replace(/url\(\s*["']?\s*(?!#)[^)]*\)/gi,'none')
    .trim();

